<?php require_once __DIR__.'/includes/auth.php';require_login(['admin']);$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT r.*,c.course_code,c.course_title,c.level,c.semester,GROUP_CONCAT(l.full_name ORDER BY l.id SEPARATOR ', ') lecturer_name,u.full_name received_by FROM result_records r JOIN courses c ON c.id=r.course_id JOIN course_lecturers cl ON cl.course_id=c.id JOIN lecturers l ON l.id=cl.lecturer_id JOIN users u ON u.id=r.created_by WHERE r.id=? GROUP BY r.id");$s->execute([$id]);$r=$s->fetch();if(!$r)exit('Acknowledgement not found.');$track=app_url('public-tracking.php?token='.$r['public_token']);?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Acknowledgement <?=e($r['tracking_no'])?></title><link rel="icon" href="favicon.ico"><link rel="stylesheet" href="css/style.css"><style>@media print{.no-print{display:none!important}.print-slip{box-shadow:none!important;border:1px solid #ddd!important}}</style></head><body class="portal-page"><main class="form-main"><div class="form-actions no-print"><a class="secondary-btn" href="admin-dashboard.php">← Dashboard</a><button class="primary-btn" onclick="window.print()">Print Slip</button></div><section class="panel print-slip" style="max-width:720px;margin:30px auto"><div style="text-align:center;border-bottom:1px solid #e4ebf3;padding-bottom:18px;margin-bottom:22px"><img src="assets/naits-logo.png" style="width:70px;height:70px;object-fit:contain"><div class="kicker">DEPARTMENT OF INFORMATION TECHNOLOGY</div><h1 style="margin:5px 0;font-size:24px">Result Receipt Acknowledgement</h1><p style="margin:0;color:#71839a;font-size:11px">IFT Result Tracking System</p></div><div class="info-grid"><div><span>Tracking No.</span><strong><?=e($r['tracking_no'])?></strong></div><div><span>Course Code</span><strong><?=e($r['course_code'])?></strong></div><div><span>Course Title</span><strong><?=e($r['course_title'])?></strong></div><div><span>Lecturers</span><strong><?=e($r['lecturer_name'])?></strong></div><div><span>Number of Scripts</span><strong><?=e($r['number_of_scripts'])?></strong></div><div><span>Level / Semester</span><strong><?=e($r['level'])?> / <?=e($r['semester'])?></strong></div><div><span>Session</span><strong><?=e($r['session_name'])?></strong></div><div><span>Received</span><strong><?=e(date('d M Y · h:i A',strtotime($r['received_at'])))?></strong></div></div><div style="margin-top:25px;padding:16px;background:#f6f9fc;border-radius:12px"><p style="font-size:11px;color:#71839a;margin:0 0 6px">Public tracking link</p><strong style="font-size:12px;word-break:break-all"><?=e($track)?></strong><p style="font-size:10px;color:#71839a;margin:10px 0 0">Use the tracking number or link to check the result status. A QR code can be added when a QR library is installed.</p></div></section></main></body></html>
